from rendu import Point
p=Point(8)
p.h('8.1 — Une déformation n’a pas un critère universel unique')
p.p('La confirmation dépend du territoire et du mécanisme : l’examen clinique caractérise la souplesse d’un pied, la rétraction de Dupuytren et le déficit actif du maillet ; la radiographie caractérise une fracture ou une courbure rachidienne ; la déformation rachitique demande un bilan phosphocalcique et étiologique. Aucun seuil commun ne peut remplacer ces démarches spécifiques.', ['p82-plat-examen', 'pa82-dupuytren-table', 'pa82-maillet-actif', 'pa82-radius-imagerie', 'p82-scoliose-radio', 'p82-xlh-mecanisme-bilan'])
p.tableau(['Entité', 'Éléments positifs', 'Limite et décision'], [
 [('Arthrose déformante de la main','p82-arthrose'),('Douleur à l’utilisation, soulagement au repos, gonflement ou déformation ; examen clinique complet.','p82-arthrose'),('L’imagerie est ciblée selon l’articulation et la question ; une déformation ne dispense pas de rechercher une articulation infectée lorsqu’elle est chaude et douloureuse.',['p82-arthrose-diagnostic','pa82-arthrite-suspecte'])],
 [('Hallux valgus','p82-hallux'),('Déviation latérale du gros orteil, déplacement médial du premier métatarsien et saillie médiale.','p82-hallux'),('Examiner réductibilité et première métatarsophalangienne ; les classifications radiographiques de sévérité sont hétérogènes et ne suffisent pas à décider une opération.',['pa82-hallux-examen','pa82-hallux-normalite'])],
 [('Pied plat valgus souple physiologique de l’enfant','pa82-plat-europe-definition'),('Pied fonctionnel, voûte effacée en charge mais reconstituée hors charge ou à la montée sur la pointe des pieds.',['pa82-plat-europe-definition','p82-plat-examen']),('L’absence de douleur et la souplesse permettent de s’abstenir d’imagerie systématique ; douleur, raideur et asymétrie changent la démarche.','pa82-plat-europe-imagerie')],
 [('Désaxation physiologique du genou de l’enfant','p82-genou'),('Évolution avec l’âge, symétrie et mesures standardisées des distances intercondylienne ou intermalléolaire.',['p82-genou','p82-genou-examen']),('Progression, asymétrie, varum après deux ans ou valgum marqué après huit ans imposent une évaluation ciblée plutôt qu’une conclusion automatique de normalité.','pa82-genou-orientation')],
 [('Doigt en maillet','pa82-maillet-actif'),('Impossibilité d’extension active de l’interphalangienne distale par rupture de l’appareil extenseur terminal.','pa82-maillet-actif'),('Rechercher ouverture et lésion unguéale ; une avulsion importante mais congruente peut relever d’une attelle avec contrôle radiographique.',['pa82-maillet-seymour','pa82-maillet-os-congruent'])],
 [('Maladie de Dupuytren','p82-dupuytren'),('Nodules et cordes palmaires, rétraction progressive ; test de la table positif si la paume et les doigts ne peuvent être posés à plat.',['p82-dupuytren','pa82-dupuytren-table']),('Le diagnostic est habituellement clinique ; les examens supplémentaires répondent à une comorbidité ou à un diagnostic différentiel.','pa82-dupuytren-examens')],
 [('Scoliose idiopathique de l’adolescent','p82-scoliose-definition'),('Courbure tridimensionnelle apparue à partir de dix ans, angle de Cobb d’au moins dix degrés associé à une rotation axiale selon la définition SRS rapportée par SOSORT.',['p82-scoliose-definition','pa82-scoliose-cobb']),('Le scoliomètre dépiste la rotation du tronc ; il ne mesure pas le Cobb et ne permet pas à lui seul de déclarer la scoliose idiopathique.',['p82-scoliose-clinique','p82-scoliose-irm'])],
 [('Fracture déplacée de l’extrémité distale du radius','p82-radius'),('Contexte traumatique et radiographies de face et de profil montrant la fracture et son déplacement.',['p82-radius','pa82-radius-imagerie']),('La radiographie ne remplace pas l’examen de la peau, des nerfs et des vaisseaux ; une menace neurovasculaire change immédiatement la priorité.',['p82-radius','pa82-radius-ischemie'])],
 [('Neuro-ostéoarthropathie de Charcot du pied diabétique','p82-charcot'),('Diabète avec neuropathie et, sur peau intacte, pied plus chaud, rouge ou gonflé que le côté opposé ; imagerie adaptée au stade.',['pa82-charcot-r1','p82-charcot']),('Des radiographies normales ne l’excluent pas ; réaliser une IRM et protéger le pied pendant le bilan.',['pa82-charcot-r8','pa82-charcot-r5'])],
 [('Rachitisme hypophosphatémique lié à l’X','p82-xlh-definition'),('Déformation rachitique, hypophosphatémie interprétée selon l’âge, fuite rénale de phosphate et mécanisme PHEX–FGF23 ; confirmation génétique.',['p82-xlh-clinique','p82-xlh-mecanisme-bilan']),('Une phosphatémie isolée ou une radiographie de rachitisme n’établissent pas seules l’étiologie XLH.',['p82-xlh-mecanisme-bilan','pa82-xlh-imagerie'])]
])
p.h('8.2 — Seuils : séparer définition, dépistage et orientation')
p.fenetre('Scoliose : seuil radiographique et signal clinique', [
 ('SOSORT 2016, publié en 2018, rapporte la définition SRS : Cobb d’au moins dix degrés avec rotation axiale sur un cliché debout. Ce seuil définit une scoliose dans ce cadre ; il n’est pas un seuil automatique de corset ou de chirurgie.', 'pa82-scoliose-cobb'),
 ('La publication pédiatrique suisse de 2023 propose une investigation radiographique devant une rotation du tronc dépassant environ cinq degrés au scoliomètre. Le seuil clinique de dépistage et le seuil radiographique de définition portent sur deux mesures différentes.', 'p82-scoliose-clinique'),
 ('La source suisse situe la prise en charge par corset et physiothérapie au-delà de vingt degrés lorsqu’une croissance reste présente. Le contexte de croissance est donc indispensable à l’interprétation du chiffre.', 'p82-scoliose-definition')])
p.fenetre('Hallux : repères angulaires et hétérogénéité des classifications', [
 ('La revue européenne rapporte comme repères normaux un angle intermétatarsien inférieur à neuf degrés et un angle d’hallux valgus inférieur à quinze degrés. Ces angles concernent des axes osseux sur l’imagerie, non l’intensité de la douleur.', 'pa82-hallux-normalite'),
 ('Un même angle intermétatarsien de quatorze degrés peut être classé différemment selon les publications. La décision doit conserver l’examen de la réductibilité, de la mobilité et de la douleur de la première métatarsophalangienne.', ['pa82-hallux-normalite','pa82-hallux-examen'])])
p.h('8.3 — Charcot : suspicion suffisante pour protéger, bilan nécessaire pour caractériser')
p.p('IWGDF 2023 recommande de considérer un Charcot actif devant les signes inflammatoires locaux chez une personne diabétique neuropathe avec peau intacte. Une immobilisation et une décharge jusqu’au genou doivent être engagées rapidement pendant la confirmation diagnostique ; attendre la preuve radiographique peut laisser progresser les lésions.', ['pa82-charcot-r1','pa82-charcot-r5'])
p.p('La CRP, la vitesse de sédimentation, les leucocytes, les phosphatases alcalines ou d’autres examens sanguins ne doivent pas servir à affirmer ou exclure un Charcot actif sur peau intacte. Cette recommandation ne signifie pas qu’un bilan infectieux soit inutile lorsqu’une infection constitue une autre hypothèse clinique.', ['pa82-charcot-r10','p82-charcot'])
p.p('La rémission se juge en combinant température, œdème et imagerie. Aucun seuil absolu de température ne suffit ; la fréquence des contrôles dépend notamment de l’évolution de l’œdème, des comorbidités, du risque du traitement et de l’aide disponible à domicile.', ['pa82-charcot-r13','pa82-charcot-r14','p82-charcot'])
p.h('8.4 — XLH : identifier le mécanisme et mesurer son retentissement')
p.p('La publication suisse de 2024 décrit une hypophosphatémie avec baisse de la réabsorption rénale, phosphatases alcalines augmentées et calcitriol inadapté au contexte. Calcium, parathormone et 25-hydroxyvitamine D peuvent rester normaux ; leur normalité ne suffit donc pas à écarter l’XLH.', 'p82-xlh-mecanisme-bilan')
p.fenetre('Un score de sévérité n’est pas un diagnostic étiologique', [
 ('Le score radiographique de rachitisme RSS s’étend de zéro, sans rachitisme radiographique, à dix pour l’atteinte la plus sévère ; il utilise les anomalies du poignet et du genou chez l’enfant. Il quantifie un retentissement osseux.', 'pa82-xlh-imagerie'),
 ('La distinction étiologique repose sur la physiologie du phosphate et le contexte génétique : PHEX, FGF23, réabsorption rénale et interprétation de la phosphatémie selon l’âge. Il faut donc relier le score d’atteinte au bilan causal.', 'p82-xlh-mecanisme-bilan')])
p.sauver()
